function slightlyAdjustColor(color) {
  const adjust = (component) => Math.max(0, Math.min(255, component + (Math.random() * 40 - 20)));
  return {
    r: adjust(color.r),
    g: adjust(color.g),
    b: adjust(color.b),
  };
}


async function itemScript(itemUUID) {
  const now = new Date();
  const timeString = now.toLocaleTimeString();

  let currentColorString = await get_string_variable("BTTClockExampleBackgroundColor");

  let currentColor = currentColorString ? JSON.parse(currentColorString) : undefined;
  if(currentColor == undefined) {
  currentColor = {
  r: Math.floor(Math.random() * 256),
  g: Math.floor(Math.random() * 256),
  b: Math.floor(Math.random() * 256),
};

  }


  await set_string_variable({variableName: "BTTClockExampleBackgroundColor", to: JSON.stringify(currentColor)});

  // Slightly change the color each time
  currentColor = slightlyAdjustColor(currentColor);

  const colorString = `${Math.round(currentColor.r)}, ${Math.round(currentColor.g)}, ${Math.round(currentColor.b)}, 180`;

  const content = {
    BTTMenuItemBackgroundColor: colorString,
    BTTMenuItemText: timeString
  };

  return JSON.stringify(content);
}
