async function summarizeGlobalKeyboardShortcuts() {
  let raw = await ai.get_trigger_json({trigger_type: 'BTTTriggerTypeKeyboardShortcut', trigger_app_bundle_identifier: 'BT.G'});
  let arr = Array.isArray(raw) ? raw : [];
  let triggers = arr.filter(t => t && t.BTTTriggerClass === 'BTTTriggerTypeKeyboardShortcut' && t.BTTTriggerType === 0);

  function mods(v) {
    const n = Number(v || 0);
    let parts = [];
    if (n & 262144) parts.push('⌃');
    if (n & 524288) parts.push('⌥');
    if (n & 1048576) parts.push('⌘');
    if (n & 8388608) parts.push('fn');
    if (n & 131072) parts.push('⇧');
    return parts.join('');
  }

  let summary = triggers.map(t => ({
    uuid: t.BTTUUID,
    shortcut: `${mods(t.BTTShortcutModifierKeys)}${t.BTTLayoutIndependentChar || t.BTTShortcutKeyCode}`,
    key: t.BTTLayoutIndependentChar || String(t.BTTShortcutKeyCode),
    enabled: t.BTTEnabled2 === 0 ? false : true,
    triggerOnDown: !!t.BTTTriggerOnDown,
    actions: Array.isArray(t.BTTActionsToExecute) ? t.BTTActionsToExecute.map(a => a.BTTPredefinedActionName || a.BTTShortcutToSend || a.BTTUUID) : []
  }));

  let duplicates = {};
  for (let item of summary) {
    duplicates[item.shortcut] = duplicates[item.shortcut] || [];
    duplicates[item.shortcut].push(item);
  }
  let duplicateShortcuts = Object.entries(duplicates)
    .filter(([k,v]) => v.length > 1)
    .map(([shortcut, items]) => ({shortcut, count: items.length, uuids: items.map(i => i.uuid)}));

  return {
    count: summary.length,
    shortcuts: summary,
    duplicateShortcuts
  };
}

