async function findHUDOverlayActions() {
  let all = [];
  let categories = [
    {trigger_type: 'BTTTriggerTypeKeyboardShortcut'},
    {trigger_type: 'BTTTriggerTypeTouchpadAll'},
    {trigger_type: 'BTTTriggerTypeFloatingMenu'},
    {trigger_type: 'BTTTriggerTypeOtherTriggers'}
  ];
  for (let cat of categories) {
    let res = await ai.get_trigger_json(cat);
    if (Array.isArray(res)) all = all.concat(res);
  }

  function walk(node, parentName) {
    let hits = [];
    if (!node || typeof node !== 'object') return hits;
    let name = node.BTTGroupName || node.BTTTriggerName || node.BTTTriggerTypeDescription || parentName || 'Unnamed';
    if (node.BTTPredefinedActionType === 254 || node.BTTPredefinedActionName === 'Show HUD Overlay') {
      hits.push({
        actionUUID: node.BTTUUID,
        parentUUID: node.BTTTriggerParentUUID || null,
        context: parentName || 'Direct action',
        actionName: node.BTTPredefinedActionName || 'Show HUD Overlay'
      });
    }
    if (Array.isArray(node.BTTActionsToExecute)) {
      for (let child of node.BTTActionsToExecute) hits = hits.concat(walk(child, name));
    }
    if (Array.isArray(node.BTTMenuItems)) {
      for (let child of node.BTTMenuItems) hits = hits.concat(walk(child, name));
    }
    if (Array.isArray(node.BTTMenuItemActions)) {
      for (let child of node.BTTMenuItemActions) hits = hits.concat(walk(child, name));
    }
    return hits;
  }

  let found = [];
  for (let item of all) found = found.concat(walk(item, item.BTTGroupName || item.BTTTriggerName || item.BTTTriggerTypeDescription));
  return found;
}

